import com.android.tools.smali.dexlib2.*;
import com.android.tools.smali.dexlib2.iface.instruction.*;
public class InspectMethods{public static void main(String[]a)throws Exception{var c=DexFileFactory.loadDexContainer(new java.io.File(a[0]),Opcodes.forDexVersion(39));for(var n:c.getDexEntryNames())for(var cl:c.getEntry(n).getDexFile().getClasses())if(cl.getType().equals(a[1]))for(var m:cl.getMethods())if(m.getName().matches(a[2])){System.out.println(m+" registers="+(m.getImplementation()==null?0:m.getImplementation().getRegisterCount()));if(m.getImplementation()!=null){int pc=0;for(var i:m.getImplementation().getInstructions()){System.out.println(pc+" "+i.getOpcode()+" "+(i instanceof OneRegisterInstruction r?r.getRegisterA():"")+" "+(i instanceof ReferenceInstruction r?r.getReference():""));pc+=i.getCodeUnits();}}}}}
